    'about.studio.list.teamGrowth': 'Künftige Team-Erweiterung',
    'about.studio.list.maintenance': 'Plattformwartung',
    'about.studio.p29': 'Damit M.NationWorld ein langfristig laufendes Produkt wird statt eines kurzfristigen Projekts.',
    'about.studio.sec.i18n': '12. Internationalisierung',
    'about.studio.p30': 'Slati Studio hat die Internationalisierung von M.NationWorld seit der Projektplanungsphase im Blick. Derzeit geplante Sprachen:',
