    'about.studio.list.zhHant': '繁体中文',
    'about.studio.list.en': 'English',
    'about.studio.list.ja': '日本語',
    'about.studio.list.ko': '한국어',
    'about.studio.list.ms': 'Bahasa Melayu',
    'about.studio.list.id': 'Bahasa Indonesia',
    'about.studio.list.th': 'ไทย',
    'about.studio.list.fr': 'Français',
    'about.studio.list.de': 'Deutsch',
    'about.studio.p31': 'Das Ziel ist, dass M.NationWorld nicht auf eine einzige Sprache oder einen einzigen Kreativkreis beschränkt bleibt, sondern eine Plattform für internationale Worldbuilding-Nutzer wird.',
    'about.studio.sec.future': '13. Langfristige Entwicklungsrichtungen',
    'about.studio.p32': 'Slati Studios Positionierung von M.NationWorld ist nicht auf die aktuelle Web-Plattform beschränkt. Mit der Entwicklung des Projekts könnten künftig erkundet werden:',
    'about.studio.list.3dWb': '3D Worldbuilding',
    'about.studio.list.3dModel': '3D-Modelle',
    'about.studio.list.gameWorld2': 'Spielwelten',
    'about.studio.list.gameTools': 'Spieleentwicklungs-Werkzeuge',
    'about.studio.list.digitalAssets': 'Digitale Assets',
    'about.studio.list.creatorTools': 'Kreativ-Werkzeuge',
    'about.studio.list.collabTools': 'Team-Kollaborations-Werkzeuge',
    'about.studio.list.wbGames': 'Worldbuilding kombiniert mit Spieleentwicklung',
    'about.studio.list.ecosystem': 'Ein vollständigeres Kreativ-Ökosystem',
    'about.studio.p33': 'M.NationWorld ist daher der zentrale Ausgangspunkt des aktuellen Vorhabens von Slati Studio, ein Worldbuilding-Ökosystem aufzubauen.',
    'about.studio.sec.organization': '14. Aktuelle Studio-Organisation',
    'about.studio.p34': 'Slati Studio befindet sich noch in der frühen Projektphase und hat daher noch nicht die vollständige Abteilungsstruktur eines traditionellen Unternehmens gebildet. Derzeit ist hauptsächlich Neo für die Kernarbeit von M.NationWorld verantwortlich. Die aktuelle Situation lässt sich so verstehen:',
    'about.studio.key.neo': '<b>Neo</b>Founder · Product Lead · UI/UX Designer · Core Developer',
    'about.studio.key.studio2': '<b>Slati Studio</b>Entwicklungsträger · Produktdesign-Träger · Träger der langfristigen Entwicklung',
    'about.studio.key.mnw2': '<b>M.NationWorld</b>Aktuelles Kernprodukt',
    'about.studio.p35': 'Wenn das Projekt in Zukunft wächst, kann Slati Studio weitere Funktionen wie Entwicklung, Design, KI, Community, Betrieb und Marketing aufbauen.',
    'about.studio.sec.positioning': '15. Die Positionierung von Slati Studio',
    'about.studio.p36': 'Insgesamt ist <b>Slati Studio</b> ein unabhängiges Entwicklungsstudio mit Schwerpunkt auf Softwareentwicklung, digitalen Kreativwerkzeugen und Worldbuilding. Derzeit ist M.NationWorld das wichtigste Produkt von Slati Studio.',
    'about.studio.p37': 'Das Hauptziel des Studios ist nicht einfach, ein Wiki zu entwickeln, sondern über M.NationWorld eine neue Art des Worldbuildings zu erkunden:',
    'about.studio.quote4': 'Jedem ermöglichen, eine eigene Welt zu erschaffen — mit der Freiheit zu entscheiden, wie diese Welt organisiert, präsentiert und weiterentwickelt wird.',
    'about.studio.p38': 'Neo ist derzeit die Kernverantwortliche Person von Slati Studio und des M.NationWorld-Projekts und übernimmt in der Frühphase zugleich die Aufgaben von Gründer, Produktverantwortlichem, Designer und Entwickler. Das Verhältnis des gesamten Projekts lässt sich daher so zusammenfassen:',
    'about.studio.chain': 'Neo<br>↓<br>Slati Studio<br>↓<br>M.NationWorld<br>↓<br>Worldbuilding Platform / Worldbuilding-Ökosystem',
    'about.studio.p39': 'Slati Studio baut das Produkt, M.NationWorld trägt die Produktphilosophie, und Neo treibt all dies Schritt für Schritt vom Konzept zum realen Softwareprodukt voran.',
    'about.studio.foot': 'Du möchtest die Studio-Mitglieder kennenlernen? Willkommen in der offiziellen Discord-Community:'
