    'about.features.canvas.title': 'Editor FluidCanvas',
    'about.features.canvas.desc': 'Editor ensiklopedia berasaskan kad dengan seretan bebas: kad teks, bendera, garis masa dan peta boleh diletak sesuka hati — tulis ensiklopedia dunia anda seperti bermain bongkah.',
    'about.features.community.title': 'Komuniti & Pakatan',
    'about.features.community.desc': 'Berinteraksi dengan pencipta lain di Community Hub: jalinkan pakatan, jalankan diplomasi dan terokai dunia masing-masing, mewujudkan hubungan sebenar antara dunia fiksyen.',
    'about.features.ai.title': 'Pembantu Kreatif AI',
    'about.features.ai.desc': 'Carian AI, pengoptimuman artikel dan ringkasan membantu anda mencari bahan, memurnikan teks dan menyusun latar dunia — anda bawa kreativiti, AI uruskan kerja kasar.',

    // ── Jenama & Kedudukan ──
    'about.brand.title': 'Jenama & Kedudukan',
    'about.brand.pill.mnw': 'M.NationWorld',
    'about.brand.pill.micronationary': 'MicroNationary',
    'about.brand.p': '<b style="color:var(--color-on-surface)">M.NationWorld</b> ialah jenama utama platform; <b style="color:var(--color-on-surface)">MicroNationary</b> ialah jenama komuniti. Kedudukan teras platform ialah <b style="color:var(--color-on-surface)">penciptaan negara fiksyen yang serius</b> — republik, sosialisme, demokrasi... setiap sistem politik dan falsafah pemerintahan boleh dipandang serius dan dibina dengan teliti di sini, bukan sekadar "negara mainan untuk bersuka-suka".',

    // ── Pasukan Kami ──
