    'about.founder.artTitle': 'Peranan & Tanggungjawab Peribadi dalam Projek M.NationWorld',
    'about.founder.sec.intro': 'Pengenalan Peribadi',
    'about.founder.meta.name': '<b>Nama</b>Neo',
    'about.founder.meta.role': '<b>Peranan Projek</b>Founder · Product Designer · UI/UX Designer · Core Developer',
    'about.founder.meta.project': '<b>Projek</b>M.NationWorld',
    'about.founder.meta.team': '<b>Pasukan Pembangunan</b>Slati Studio',
    'about.founder.meta.stage': '<b>Peringkat Semasa</b>Pembangunan bebas peringkat awal',
    'about.founder.p1': 'Neo ialah pengasas projek M.NationWorld, pereka produk terasnya, dan satu-satunya pembangun pada peringkat awal projek. Kini beliau menguruskan sebahagian besar kerja teras M.NationWorld — daripada visi konsep, kedudukan produk dan perancangan ciri hingga ke reka bentuk UI/UX dan pembangunan sebenar.',
    'about.founder.p2': 'Oleh kerana projek masih di peringkat awal, Neo pada masa yang sama memikul tanggungjawab yang lazimnya diagihkan kepada beberapa peranan berbeza dalam pasukan pembangunan, termasuk ketua projek, pengurus produk, pereka UI/UX, ketua teknikal dan pembangun. Kesannya, hala tuju produk, sistem reka bentuk dan pelaksanaan teknikal M.NationWorld kini diterajui terutamanya oleh Neo.',
    'about.founder.sec.vision': 'Visi Projek & Kedudukan Produk',
