    'about.founder.p4': 'Projek ini bermula dengan idea Wiki negara fiksyen; melalui reka bentuk dan pelarasan produk yang berterusan, ia berkembang menjadi <b>Platform Worldbuilding</b> untuk kalangan pencipta yang jauh lebih luas.',
    'about.founder.p5': 'Oleh itu, salah satu tugas utama Neo ialah sentiasa memikirkan semula nilai teras M.NationWorld, termasuk:',
    'about.founder.list.need': 'Mengapa pengguna memerlukan M.NationWorld',
