    'about.founder.p6': 'Neo berharap M.NationWorld akhirnya bukan sekadar Wiki tradisional, tetapi platform penciptaan komprehensif yang membolehkan pengguna <b>mencipta, menyusun, mempamer, berkongsi dan terus membangunkan dunia mereka sendiri</b>.',
    'about.founder.sec.product': 'Reka Bentuk Produk & Ciri',
    'about.founder.p7': 'Pada peringkat produk, Neo bertanggungjawab merancang keseluruhan seni bina ciri M.NationWorld serta hubungan antara sistem-sistemnya.',
    'about.founder.p8': 'Hala tuju utama yang kini terlibat termasuk:',
    'about.founder.list.wb': 'Worldbuilding / penciptaan dunia',
    'about.founder.list.wiki': 'Wiki',
    'about.founder.list.edit': 'Penyuntingan kandungan',
