    'about.founder.list.contentMgmt': 'Pengurusan kandungan',
    'about.founder.list.aiService': 'Perkhidmatan AI',
    'about.founder.list.governance': 'Tadbir urus platform',
    'about.founder.list.userSub': 'Langganan pengguna',
    'about.founder.list.teamSub': 'Langganan pasukan',
    'about.founder.p9': 'Neo mereka bentuk ciri-ciri ini berdasarkan keperluan pengguna, dan memikirkan bagaimana ia membentuk platform yang lengkap dan bukannya modul fungsi yang terpisah.',
    'about.founder.sec.uiux': 'Reka Bentuk UI / UX',
    'about.founder.p10': 'Neo juga bertanggungjawab terhadap keseluruhan reka bentuk UI/UX dan bahasa reka bentuk M.NationWorld.',
    'about.founder.p11': 'Ini termasuk reka bentuk teras seperti Card UI, paparan kandungan modular, latar belakang Wiki dinamik, halaman yang sangat boleh disesuaikan serta FluidCanvas.',
    'about.founder.p12': 'Proses reka bentuk menumpukan dua aspek:',
    'about.founder.key.freedom': '<b>Kebebasan</b>Pengguna boleh melaraskan halaman secara bebas mengikut keperluan dunia dan kandungan mereka, dan bukannya terhad kepada templat tetap.',
    'about.founder.key.ease': '<b>Kemudahan</b>Walaupun pengguna tiada pengetahuan pembangunan web profesional, mereka boleh mencipta dan mengurus kandungan yang kompleks dengan alat visual.',
    'about.founder.p13': 'Oleh itu, hala tuju reka bentuk M.NationWorld bukan sekadar mengejar kesan visual, tetapi membina <b>persekitaran penciptaan yang sangat boleh disesuaikan</b> yang benar-benar berkhidmat untuk pencipta.',
    'about.founder.sec.fc': 'FluidCanvas & Alat Penciptaan',
    'about.founder.p14': 'Neo bertanggungjawab merancang logik produk FluidCanvas, sebuah konsol peringkat pertengahan.',
    'about.founder.p15': 'FluidCanvas menghubungkan penciptaan kandungan dengan pengurusan data di M.NationWorld, termasuk penyuntingan artikel, pengurusan kandungan serta paparan data seperti tontonan, sukaan dan kegemaran.',
    'about.founder.p16': 'Falsafah terasnya ialah:',
    'about.founder.quote1': 'Ubah keupayaan pengurusan kandungan yang kompleks menjadi alat penciptaan yang intuitif dan visual.',
    'about.founder.p17': 'Ini juga merupakan cerminan penting falsafah reka bentuk produk Neo untuk M.NationWorld.',
    'about.founder.sec.dev': 'Pembangunan Projek',
    'about.founder.p18': 'Kini Neo ialah <b>satu-satunya pembangun teras M.NationWorld pada peringkat awalnya</b>.',
    'about.founder.p19': 'Oleh kerana projek berada di peringkat awal, pembangunan dijalankan terutamanya melalui <b>AI-assisted Development</b>, menggunakan alat AI seperti DeepSeek untuk membantu penulisan kod, analisis kod, penyahpepijatan dan penyelesaian masalah.',
    'about.founder.p20': 'AI digunakan terutamanya sebagai alat pembangunan, manakala keputusan produk, hala tuju teknikal dan pelaksanaan akhir kekal menjadi tanggungjawab Neo.',
    'about.founder.p21': 'Secara khusus, Neo bertanggungjawab untuk:',
