    'about.founder.list.integrate': 'Mengubah suai dan menyepadukan kod',
    'about.founder.list.debug': 'Menyahpepijat projek',
    'about.founder.list.test': 'Menguji fungsi',
    'about.founder.list.solve': 'Menyelesaikan masalah yang timbul semasa pembangunan',
    'about.founder.list.ship': 'Memutuskan sama ada sesuatu fungsi masuk ke produk rasmi',
    'about.founder.p22': 'Oleh itu, model pembangunan semasa M.NationWorld boleh diringkaskan sebagai:',
    'about.founder.key.humanAi': '<b>Human-led · AI-assisted</b>',
    'about.founder.p23': 'Iaitu, manusia membuat keputusan produk dan teknikal, manakala AI memberi bantuan pembangunan.',
    'about.founder.sec.governance': 'Komuniti & Tadbir Urus Platform',
    'about.founder.p24': 'Neo juga bertanggungjawab merancang sistem komuniti M.NationWorld serta mekanisme tadbir urus platform.',
    'about.founder.p25': 'Platform ini bukan sahaja menyediakan alat worldbuilding pada masa hadapan, tetapi juga berharap membentuk komuniti di mana pencipta berkomunikasi, bekerjasama dan berkongsi karya.',
    'about.founder.p26': 'Oleh itu, Neo merancang ciri seperti hantaran, mesej langsung, Channel, Team, data pencipta dan interaksi komuniti, di samping memikirkan peraturan platform, penyederhanaan kandungan dan sistem pengurusan pengguna.',
    'about.founder.p27': 'Dari segi aplikasi AI, Neo merancang penggunaan AI untuk penyederhanaan kandungan, sokongan pelanggan AI, integrasi data, ringkasan kandungan dan bantuan pengurusan platform.',
    'about.founder.p28': 'Apabila AI tidak dapat menentukan sama ada kandungan tertentu mematuhi peraturan platform, penyederhanaan manusia menjadi pelengkap.',
    'about.founder.sec.business': 'Pengkomersialan & Pembangunan Jangka Panjang',
    'about.founder.p29': 'Selain pembangunan produk semasa, Neo juga bertanggungjawab memikirkan model perniagaan M.NationWorld dan pelan jangka panjangnya.',
    'about.founder.p30': 'Hala tuju yang dirancang kini termasuk:',
    'about.founder.list.freeTier': 'Sistem pengguna percuma',
    'about.founder.list.proSub': 'Langganan Pro / premium',
    'about.founder.list.enterprise': 'Enterprise / perkhidmatan premium',
    'about.founder.list.teamChannelSub': 'Langganan Team / Channel',
    'about.founder.list.ads': 'Pengiklanan',
    'about.founder.list.creatorSvc': 'Perkhidmatan pencipta',
    'about.founder.list.i18n': 'Pengantarabangsaan & sokongan pelbagai bahasa',
    'about.founder.list.3d': 'Kandungan 3D',
    'about.founder.list.games': 'Permainan & pengembangan dunia digital',
    'about.founder.p31': 'Neo berharap M.NationWorld dapat berkembang daripada projek peribadi menjadi sebuah Worldbuilding Ecosystem yang lengkap.',
    'about.founder.sec.position': 'Kedudukan Peribadi Semasa',
    'about.founder.p32': 'Oleh kerana projek masih di peringkat awal, peranan Neo bukan sekadar "pembangun".',
    'about.founder.p33': 'Gambaran yang lebih tepat tentang kedudukannya kini ialah:',
    'about.founder.key.founder': '<b>Founder</b>Bertanggungjawab terhadap hala tuju keseluruhan dan keputusan teras projek.',
    'about.founder.key.pd': '<b>Product Designer</b>Bertanggungjawab terhadap kedudukan produk, sistem ciri dan pengalaman pengguna.',
    'about.founder.key.uiux': '<b>UI/UX Designer</b>Bertanggungjawab terhadap bahasa visual keseluruhan, antara muka dan reka bentuk interaksi.',
    'about.founder.key.cd': '<b>Core Developer</b>Bertanggungjawab terhadap pembangunan sebenar, pelaksanaan teknikal, penyahpepijatan dan ujian pada peringkat awal projek.',
    'about.founder.p34': 'Oleh itu, Neo kini memainkan peranan teras yang menghubungkan <b>kreativiti, produk, reka bentuk dan teknologi</b>.',
    'about.founder.sec.summary': 'Ringkasan',
    'about.founder.p35': 'Kini, Neo ialah individu paling penting dalam perjalanan projek M.NationWorld daripada konsep kepada produk sebenar.',
    'about.founder.p36': 'Daripada mencetuskan visi asal projek, menentukan kedudukan platform worldbuilding, mereka bentuk sistem seperti Wiki, komuniti, FluidCanvas dan Card UI, hingga menyiapkan pembangunan sebenar dengan bantuan AI — Neo memacu keseluruhan kitaran hayat produk awal M.NationWorld.',
    'about.founder.p37': 'Ringkasnya:',
    'about.founder.quote2': 'Neo bertanggungjawab memikirkan apa yang sepatutnya M.NationWorld, mereka bentuk bagaimana ia sepatutnya berfungsi, dan sendiri membangunkan idea-idea ini langkah demi langkah menjadi produk sebenar.',
    'about.founder.p38': 'Apabila projek berkembang pada masa hadapan, tanggungjawab ini boleh diagihkan secara beransur-ansur kepada ahli pasukan yang berbeza. Namun pada peringkat awal ini, Neo serentak memikul peranan <b>pengasas, pereka produk dan pembangun teras</b> — penggerak produk dan teknologi terpenting M.NationWorld hari ini.',
    'about.founder.foot': 'Nak kenali pengasasnya? Selamat datang ke komuniti Discord rasmi:',

    // ── Modal Studio ──
    'about.studio.name': 'Slati Studio',
    'about.studio.role': 'Studio Pembangunan · Entiti Projek Teras',
    'about.studio.artTitle': 'Pengenalan Terperinci Slati Studio dalam Projek M.NationWorld',
    'about.studio.sec.intro': '1. Pengenalan Slati Studio',
    'about.studio.p1': '<b>Slati Studio</b> ialah studio pembangunan dan entiti projek teras bagi projek M.NationWorld, bertanggungjawab terhadap konsep produk, reka bentuk, pembangunan dan pertumbuhan jangka panjang M.NationWorld.',
    'about.studio.p2': 'Slati Studio kini berada di peringkat awal, dan M.NationWorld ialah projek teras paling penting studio buat masa ini.',
    'about.studio.p3': 'Tidak seperti syarikat perisian tradisional dengan pelbagai jabatan dan ramai pekerja, Slati Studio kini beroperasi dalam model pembangunan individu yang ringkas. Pada peringkat awal M.NationWorld, Neo serentak memikul pelbagai peranan termasuk ketua projek, pereka produk, pereka UI/UX dan pembangun teras.',
    'about.studio.p4': 'Oleh itu, pada peringkat ini Slati Studio lebih hampir kepada <b>Independent Software Studio</b> yang diterajui pengasasnya.',
    'about.studio.sec.relation': '2. Hubungan dengan M.NationWorld',
    'about.studio.p5': 'Hubungan antara Slati Studio dan M.NationWorld boleh diringkaskan sebagai:',
    'about.studio.key.studio': '<b>Slati Studio</b>→ Studio pembangunan',
    'about.studio.key.mnw': '<b>M.NationWorld</b>→ Produk teras',
    'about.studio.p6': 'M.NationWorld ialah projek produk terpenting Slati Studio buat masa ini. Slati Studio bertanggungjawab terhadap keseluruhan pembinaan M.NationWorld, termasuk kedudukan produk, reka bentuk ciri, UI/UX, pembangunan teknikal, aplikasi AI, tadbir urus platform dan perancangan pembangunan masa hadapan.',
    'about.studio.p7': 'Oleh itu, M.NationWorld bukan sekadar projek web peribadi, tetapi projek perisian jangka panjang yang dibangunkan dan dirancang secara berterusan oleh Slati Studio.',
    'about.studio.sec.duties': '3. Tanggungjawab Teras',
    'about.studio.p8': 'Tanggungjawab Slati Studio dalam projek M.NationWorld bukan sekadar "menulis kod". Studio ini bertanggungjawab mengambil konsep produk dan mengubahnya secara beransur-ansur menjadi platform perisian yang lengkap. Tanggungjawab utama termasuk:',
    'about.studio.sub.planning': 'Perancangan Produk',
    'about.studio.p9': 'Bertanggungjawab menentukan M.NationWorld dari segi:',
    'about.studio.list.positioning': 'Kedudukan produk',
    'about.studio.list.audience': 'Kumpulan sasaran',
    'about.studio.list.coreFeatures': 'Ciri teras',
