    'about.studio.list.bizModel': 'Model perniagaan',
    'about.studio.list.globalDir': 'Hala tuju pengantarabangsaan',
    'about.studio.list.roadmap': 'Pelan pembangunan jangka panjang',
    'about.studio.p10': 'M.NationWorld pada mulanya berkisar pada Wiki negara fiksyen, kemudian secara beransur-ansur beralih kepada <b>Platform Worldbuilding</b> yang lebih luas.',
    'about.studio.p11': 'Pelarasan kedudukan ini juga merupakan hasil perancangan semula hala tuju jangka panjang projek oleh Slati Studio.',
    'about.studio.sec.wbPlatform': '4. Pembinaan Platform Worldbuilding',
    'about.studio.p12': 'Slati Studio bertanggungjawab membina sistem Worldbuilding teras M.NationWorld. Matlamatnya bukan sekadar menyediakan Wiki, tetapi membolehkan pengguna mencipta, menyusun, mempamer dan terus menyelenggara dunia mereka sendiri secara bebas. Jenis kandungan yang dirancang untuk masa hadapan termasuk:',
    'about.studio.list.nation': 'Negara fiksyen',
    'about.studio.list.history': 'Sejarah alternatif',
    'about.studio.list.city': 'Bandar fiksyen',
