    'about.studio.list.politics': 'Sistem politik',
    'about.studio.list.gameWorld': 'Dunia permainan',
    'about.studio.list.novelWorld': 'Dunia novel',
    'about.studio.list.oc': 'OC',
    'about.studio.list.animeWorld': 'Dunia anime',
    'about.studio.list.teamWorld': 'Dunia asli pasukan',
    'about.studio.p13': 'Oleh itu, Slati Studio berharap M.NationWorld akhirnya membentuk persekitaran worldbuilding yang lebih terbuka. Falsafah terasnya boleh diringkaskan sebagai:',
    'about.studio.quote1': 'Beri pengguna kebebasan berkarya setinggi mungkin, di samping merendahkan halangan mencipta dunia yang kompleks.',
    'about.studio.sec.product': '5. Reka Bentuk Produk & Ciri',
    'about.studio.p14': 'Slati Studio bertanggungjawab terhadap keseluruhan struktur produk dan reka bentuk ciri M.NationWorld. Sistem teras yang dirancang kini termasuk:',
    'about.studio.list.wb': 'Worldbuilding',
    'about.studio.list.wiki': 'Wiki',
    'about.studio.list.wysiwyg': 'Penyuntingan kandungan WYSIWYG',
