    'about.studio.list.userSub': 'Langganan pengguna',
    'about.studio.list.teamSub': 'Langganan pasukan',
    'about.studio.p15': 'Ciri-ciri ini tidak wujud secara berasingan; semuanya digabungkan mengelilingi teras "penciptaan dunia". Matlamatnya ialah membentuk aliran kerja lengkap: <b>cipta → edit → terbit → pamer → berkomunikasi → bekerjasama → urus</b>.',
    'about.studio.sec.uiux': '6. Reka Bentuk UI/UX',
    'about.studio.p16': 'Slati Studio bertanggungjawab terhadap keseluruhan reka bentuk visual dan sistem interaksi M.NationWorld. Ini termasuk:',
    'about.studio.list.cardUi2': 'Card UI',
    'about.studio.list.modular': 'Halaman modular',
