    'about.studio.p17': 'Slati Studio memberi penekanan khusus kepada <b>pengalaman penyesuaian</b>. Wiki tradisional sering menghendaki pengguna mencipta kandungan dalam struktur tetap, manakala M.NationWorld mahu pengguna lebih bebas menentukan cara dunia mereka dipersembahkan.',
    'about.studio.p18': 'Oleh itu, matlamat reka bentuk UI/UX bukan sekadar "nampak cantik", tetapi:',
    'about.studio.quote2': 'Membolehkan pengguna benar-benar mengawal kandungan mereka sendiri.',
    'about.studio.sec.fc': '7. FluidCanvas',
    'about.studio.p19': '<b>FluidCanvas</b> ialah alat penciptaan dan pengurusan penting dalam sistem M.NationWorld. Slati Studio bertanggungjawab terhadap reka bentuk produk dan perancangan ciri FluidCanvas. Ia digunakan terutamanya untuk:',
    'about.studio.list.editArticle': 'Menyunting artikel',
    'about.studio.list.mgmtWiki': 'Mengurus kandungan Wiki',
    'about.studio.list.mgmtPosts': 'Mengurus hantaran',
