    'about.studio.list.viewViews': 'Melihat jumlah tontonan',
    'about.studio.list.viewLikes': 'Melihat jumlah sukaan',
    'about.studio.list.viewFavs': 'Melihat jumlah kegemaran',
    'about.studio.list.viewCreatorData': 'Melihat data pencipta',
    'about.studio.list.mgmtTeamData': 'Mengurus data pasukan',
    'about.studio.p20': 'FluidCanvas diletakkan sebagai konsol peringkat pertengahan yang menghubungkan antara muka pengguna biasa dengan data asas platform. Falsafah terasnya ialah:',
    'about.studio.quote3': 'Ubah fungsi pengurusan data dan kandungan yang kompleks menjadi ruang kerja visual yang intuitif.',
    'about.studio.sec.dev': '8. Pembangunan Perisian',
    'about.studio.p21': 'Slati Studio bertanggungjawab terhadap pembangunan perisian sebenar M.NationWorld. Projek masih di peringkat awal, jadi pembangunan diuruskan terutamanya oleh Neo seorang diri. Pembangunan mengikuti model <b>AI-assisted Development</b>, menggunakan alat AI seperti DeepSeek untuk membantu:',
    'about.studio.list.code': 'Penulisan kod',
    'about.studio.list.analysis': 'Analisis kod',
    'about.studio.list.impl': 'Pelaksanaan fungsi',
    'about.studio.list.debug': 'Debug',
    'about.studio.list.troubleshoot': 'Penyelesaian masalah',
    'about.studio.list.modify': 'Pengubahsuaian kod',
    'about.studio.list.research': 'Penyelidikan teknikal',
    'about.studio.p22': 'Namun AI tidak membuat keputusan muktamad projek. Keperluan produk, hala tuju teknikal, logik fungsi, semakan kod, pengubahsuaian, integrasi, ujian dan penerimaan akhir sesuatu pelan pelaksanaan kekal menjadi tanggungjawab Neo. Oleh itu, model pembangunan semasa Slati Studio boleh diringkaskan sebagai:',
    'about.studio.key.humanLed': '<b>Human-led Development + AI-assisted Development</b>Iaitu: manusia membuat keputusan, AI membantu pembangunan.',
    'about.studio.sec.ai': '9. Aplikasi AI',
    'about.studio.p23': 'Slati Studio merancang menjadikan AI sebahagian daripada infrastruktur platform M.NationWorld, bukan sekadar fungsi sembang. Pada masa hadapan, AI boleh terlibat dalam:',
    'about.studio.list.moderation': 'Penyederhanaan kandungan',
    'about.studio.list.uploadReview': 'Semakan muat naik',
    'about.studio.list.aiSupport': 'Sokongan pelanggan AI',
    'about.studio.list.summary': 'Ringkasan kandungan',
    'about.studio.list.dataInteg': 'Integrasi data',
    'about.studio.list.categorize': 'Pengelasan kandungan',
    'about.studio.list.creatorAssist': 'Bantuan pencipta',
    'about.studio.list.platformMgmt': 'Pengurusan platform',
    'about.studio.p24': 'Apabila AI tidak dapat menentukan sama ada kandungan tertentu mematuhi peraturan platform, ia diserahkan kepada manusia untuk semakan lanjut. Oleh itu, Slati Studio berharap membina mekanisme pengurusan hibrid <b>automasi AI + penyederhanaan manusia</b>.',
    'about.studio.sec.community': '10. Komuniti & Ekosistem Pencipta',
    'about.studio.p25': 'Slati Studio bertanggungjawab merancang ekosistem komuniti M.NationWorld. Matlamat platform bukanlah pengguna pergi selepas mencipta Wiki, tetapi mereka membentuk penciptaan dan komunikasi jangka panjang di sekitar dunia mereka. Oleh itu, ia merancang untuk mewujudkan:',
    'about.studio.list.posts2': 'Hantaran',
    'about.studio.list.dm2': 'Mesej langsung',
    'about.studio.list.channel2': 'Channel',
    'about.studio.list.team2': 'Team',
    'about.studio.list.creatorHome2': 'Profil pencipta',
    'about.studio.list.like2': 'Sukaan',
    'about.studio.list.fav2': 'Kegemaran',
    'about.studio.list.views2': 'Tontonan',
    'about.studio.list.interaction': 'Interaksi komuniti',
    'about.studio.list.collab': 'Kerjasama pasukan',
    'about.studio.p26': 'Akhirnya membentuk komuniti pencipta yang berpusat pada Worldbuilding.',
    'about.studio.sec.business': '11. Pengkomersialan & Perancangan Operasi',
    'about.studio.p27': 'Slati Studio juga bertanggungjawab mereka bentuk model perniagaan M.NationWorld. Pendekatan yang mungkin pada masa hadapan termasuk:',
    'about.studio.list.freeUser': 'Pengguna percuma',
