    'about.studio.list.ads': 'Pengiklanan',
    'about.studio.p28': 'dan pendekatan lain. Tujuan utama pengkomersialan ialah membiayai pembangunan berterusan platform, termasuk:',
    'about.studio.list.servers': 'Pelayan',
    'about.studio.list.storage': 'Penyimpanan data',
