    'about.studio.list.maintenance': 'Penyelenggaraan platform',
    'about.studio.p29': 'Supaya M.NationWorld dapat menjadi produk yang beroperasi jangka panjang, bukan projek jangka pendek.',
    'about.studio.sec.i18n': '12. Pengantarabangsaan',
    'about.studio.p30': 'Slati Studio mempertimbangkan pengantarabangsaan M.NationWorld sejak peringkat perancangan projek lagi. Sokongan yang dirancang kini termasuk:',
    'about.studio.list.zh': '简体中文',
    'about.studio.list.zhHant': '繁体中文',
    'about.studio.list.en': 'English',
    'about.studio.list.ja': '日本語',
    'about.studio.list.ko': '한국어',
    'about.studio.list.ms': 'Bahasa Melayu',
    'about.studio.list.id': 'Bahasa Indonesia',
    'about.studio.list.th': 'ไทย',
    'about.studio.list.fr': 'Français',
    'about.studio.list.de': 'Deutsch',
    'about.studio.p31': 'Matlamatnya ialah supaya M.NationWorld tidak terhad kepada satu bahasa atau satu kelompok pencipta sahaja, tetapi menjadi platform untuk pengguna Worldbuilding antarabangsa.',
    'about.studio.sec.future': '13. Hala Tuju Pembangunan Jangka Panjang',
    'about.studio.p32': 'Kedudukan M.NationWorld oleh Slati Studio tidak terhad kepada platform Web semasa. Seiring perkembangan projek, ia mungkin terus meneroka:',
    'about.studio.list.3dWb': '3D Worldbuilding',
    'about.studio.list.3dModel': 'Model 3D',
    'about.studio.list.gameWorld2': 'Dunia permainan',
    'about.studio.list.gameTools': 'Alat pembangunan permainan',
    'about.studio.list.digitalAssets': 'Aset digital',
    'about.studio.list.creatorTools': 'Alat pencipta',
    'about.studio.list.collabTools': 'Alat kerjasama pasukan',
    'about.studio.list.wbGames': 'Worldbuilding digabungkan dengan pembangunan permainan',
    'about.studio.list.ecosystem': 'Ekosistem pencipta yang lebih lengkap',
    'about.studio.p33': 'Oleh itu, M.NationWorld ialah titik permulaan teras usaha semasa Slati Studio untuk membina ekosistem Worldbuilding.',
    'about.studio.sec.organization': '14. Bentuk Organisasi Studio Semasa',
    'about.studio.p34': 'Slati Studio masih berada di peringkat awal projek, jadi ia belum membentuk struktur jabatan lengkap seperti syarikat tradisional. Buat masa ini, Neo bertanggungjawab terutamanya terhadap kerja teras M.NationWorld. Keadaan semasa boleh difahami sebagai:',
    'about.studio.key.neo': '<b>Neo</b>Founder · Product Lead · UI/UX Designer · Core Developer',
    'about.studio.key.studio2': '<b>Slati Studio</b>Entiti pembangunan · entiti reka bentuk produk · entiti pembangunan jangka panjang',
    'about.studio.key.mnw2': '<b>M.NationWorld</b>Produk teras semasa',
    'about.studio.p35': 'Apabila projek berkembang pada masa hadapan, Slati Studio boleh mewujudkan fungsi berbeza seperti pembangunan, reka bentuk, AI, komuniti, operasi dan pemasaran.',
    'about.studio.sec.positioning': '15. Kedudukan Slati Studio',
    'about.studio.p36': 'Kesimpulannya, <b>Slati Studio</b> ialah studio pembangunan bebas yang tertumpu pada pembangunan perisian, alat penciptaan digital dan Worldbuilding. Buat masa ini, M.NationWorld ialah produk paling teras Slati Studio.',
    'about.studio.p37': 'Matlamat utama studio bukan sekadar membangunkan Wiki, tetapi meneroka cara baharu penciptaan dunia melalui M.NationWorld:',
    'about.studio.quote4': 'Membolehkan sesiapa sahaja mencipta dunia mereka sendiri, dengan kebebasan menentukan cara dunia itu disusun, dipersembah dan dibangunkan.',
    'about.studio.p38': 'Neo kini ialah orang teras yang bertanggungjawab ke atas Slati Studio dan projek M.NationWorld, memikul tugas pengasas, ketua produk, pereka dan pembangun pada peringkat awal projek. Oleh itu, hubungan keseluruhan projek boleh diringkaskan sebagai:',
    'about.studio.chain': 'Neo<br>↓<br>Slati Studio<br>↓<br>M.NationWorld<br>↓<br>Worldbuilding Platform / ekosistem penciptaan dunia',
    'about.studio.p39': 'Slati Studio membina produk, M.NationWorld membawa falsafah produk, dan Neo memacu semua ini langkah demi langkah daripada konsep menjadi produk perisian sebenar.',
    'about.studio.foot': 'Nak kenali ahli studio? Selamat datang ke komuniti Discord rasmi:'
