    'about.who.p2': 'เราเชื่อว่าทุกคนมีโลกที่อยากสร้าง M.NationWorld ตั้งใจลดอุปสรรคในการสร้างสรรค์ให้ต่ำที่สุด — เพื่อให้ครีเอเตอร์ทั่วไปที่ไม่รู้เรื่องเขียนโค้ดหรือออกแบบ ก็สร้างชาติของตัวเองได้เหมือนต่อบล็อก',
