    'about.brand.p': '<b style="color:var(--color-on-surface)">M.NationWorld</b> คือแบรนด์หลักของแพลตฟอร์ม <b style="color:var(--color-on-surface)">MicroNationary</b> คือแบรนด์ของชุมชน ตำแหน่งหลักของแพลตฟอร์มคือ<b style="color:var(--color-on-surface)">การสร้างชาติจำลองแบบจริงจัง</b> — สาธารณรัฐ สังคมนิยม ประชาธิปไตย… ทุกระบบการเมืองและแนวคิดการปกครองได้รับการปฏิบัติอย่างจริงจังและสร้างอย่างพิถีพิถันได้ที่นี่ ไม่ใช่แค่ "ชาติของเล่นไว้เล่นขำ ๆ"',

