    'about.founder.name': 'TChest_Neo24',
    'about.founder.role': 'ผู้ก่อตั้ง · นักออกแบบผลิตภัณฑ์ · นักออกแบบ UI/UX · นักพัฒนาหลัก',
    'about.founder.artTitle': 'บทบาทและหน้าที่ส่วนตัวในโปรเจกต์ M.NationWorld',
    'about.founder.sec.intro': 'แนะนำตัว',
    'about.founder.meta.name': '<b>ชื่อ</b>Neo',
    'about.founder.meta.role': '<b>บทบาทในโปรเจกต์</b>Founder · Product Designer · UI/UX Designer · Core Developer',
    'about.founder.meta.project': '<b>โปรเจกต์</b>M.NationWorld',
    'about.founder.meta.team': '<b>ทีมพัฒนา</b>Slati Studio',
    'about.founder.meta.stage': '<b>ขั้นตอนปัจจุบัน</b>พัฒนาอิสระระยะเริ่มต้น',
    'about.founder.p1': 'Neo คือผู้ริเริ่มโปรเจกต์ M.NationWorld นักออกแบบผลิตภัณฑ์คนสำคัญ และนักพัฒนาเพียงคนเดียวในช่วงแรกของโปรเจกต์ ปัจจุบันเขาดูแลงานหลักส่วนใหญ่ของ M.NationWorld ตั้งแต่แนวคิด ตำแหน่งผลิตภัณฑ์ การวางแผนฟีเจอร์ ไปจนถึงการออกแบบ UI/UX และการพัฒนาจริง',
    'about.founder.p2': 'เนื่องจากโปรเจกต์ยังอยู่ในช่วงแรก Neo จึงรับหน้าที่ที่ตามปกติต้องกระจายให้หลายบทบาทในทีมพัฒนาไปพร้อมกัน ทั้งหัวหน้าโปรเจกต์ ผู้จัดการผลิตภัณฑ์ นักออกแบบ UI/UX หัวหน้าฝ่ายเทคนิค และนักพัฒนา ด้วยเหตุนี้ ทิศทางผลิตภัณฑ์ ระบบการออกแบบ และการนำไปใช้ทางเทคนิคของ M.NationWorld จึงขับเคลื่อนโดย Neo เป็นหลักในปัจจุบัน',
    'about.founder.sec.vision': 'วิสัยทัศน์โปรเจกต์และการวางตำแหน่งผลิตภัณฑ์',
    'about.founder.p3': 'Neo รับผิดชอบหลักในการกำหนดทิศทางผลิตภัณฑ์และการวางตำแหน่งระยะยาวของ M.NationWorld',
    'about.founder.p4': 'โปรเจกต์เริ่มจากแนวคิด Wiki ชาติจำลอง แล้วค่อย ๆ พัฒนาไปเป็น<b>แพลตฟอร์มสร้างโลก (Worldbuilding Platform)</b> สำหรับครีเอเตอร์ที่หลากหลายขึ้นผ่านการออกแบบและปรับปรุงผลิตภัณฑ์อย่างต่อเนื่อง',
    'about.founder.p5': 'ดังนั้น หนึ่งในงานหลักของ Neo คือทบทวนคุณค่าหลักของ M.NationWorld อยู่เสมอ ได้แก่:',
