    'about.founder.list.teamSupport': 'แพลตฟอร์มสนับสนุนการสร้างสรรค์แบบเดี่ยวและทีมอย่างไร',
    'about.founder.list.aiRole': 'AI ควรมีส่วนร่วมในการทำงานของแพลตฟอร์มอย่างไร',
    'about.founder.list.ecosystem': 'แพลตฟอร์มจะสร้างระบบนิเวศครีเอเตอร์ที่สมบูรณ์ได้อย่างไรในอนาคต',
    'about.founder.p6': 'Neo หวังว่า M.NationWorld จะไม่ใช่แค่ Wiki แบบดั้งเดิม แต่เป็นแพลตฟอร์มสร้างสรรค์ครบวงจรที่ให้ผู้ใช้<b>สร้าง จัดระเบียบ นำเสนอ แบ่งปัน และพัฒนาโลกของตัวเองอย่างต่อเนื่อง</b>',
