    'about.founder.p9': 'Neo ออกแบบฟีเจอร์เหล่านี้จากความต้องการของผู้ใช้ และคิดว่ามันจะประกอบกันเป็นแพลตฟอร์มที่สมบูรณ์ ไม่ใช่โมดูลฟังก์ชันที่แยกกันอย่างไร',
