    'about.founder.p11': 'รวมถึงการออกแบบหลักอย่าง Card UI การแสดงเนื้อหาแบบโมดูล พื้นหลัง Wiki แบบไดนามิก หน้าเพจที่ปรับแต่งได้สูง และ FluidCanvas',
    'about.founder.p12': 'กระบวนการออกแบบเน้นสองประเด็น:',
    'about.founder.key.freedom': '<b>อิสระ</b>ผู้ใช้ปรับหน้าเพจได้อย่างอิสระตามความต้องการของโลกและเนื้อหา โดยไม่ถูกจำกัดด้วยเทมเพลตตายตัว',
    'about.founder.key.ease': '<b>ใช้งานง่าย</b>แม้ผู้ใช้ไม่มีความรู้ด้านการพัฒนาเว็บระดับมืออาชีพ ก็สร้างและจัดการเนื้อหาที่ซับซ้อนได้ด้วยเครื่องมือแบบเห็นภาพ',
    'about.founder.p13': 'ดังนั้น ทิศทางการออกแบบของ M.NationWorld จึงไม่ใช่การไล่ตามเอฟเฟกต์ภาพเพียงอย่างเดียว แต่คือการสร้าง<b>สภาพแวดล้อมการสร้างสรรค์ที่ปรับแต่งได้สูง</b>ที่ตอบโจทย์ครีเอเตอร์จริง ๆ',
    'about.founder.sec.fc': 'FluidCanvas และเครื่องมือสร้างสรรค์',
    'about.founder.p14': 'Neo รับผิดชอบวางแผนตรรกะผลิตภัณฑ์ของ FluidCanvas คอนโซลระดับกลาง',
    'about.founder.p15': 'FluidCanvas เชื่อมการสร้างเนื้อหากับการจัดการข้อมูลของ M.NationWorld ทั้งการแก้ไขบทความ การจัดการเนื้อหา และการดูข้อมูลอย่างยอดวิว ไลก์ และรายการโปรด',
    'about.founder.p16': 'แนวคิดหลักคือ:',
    'about.founder.quote1': 'เปลี่ยนความสามารถจัดการเนื้อหาที่ซับซ้อนให้เป็นเครื่องมือสร้างสรรค์ที่ใช้งานง่ายและเห็นภาพ',
    'about.founder.p17': 'นี่คือการสะท้อนปรัชญาการออกแบบผลิตภัณฑ์ของ Neo สำหรับ M.NationWorld ที่สำคัญด้วย',
    'about.founder.sec.dev': 'การพัฒนาโปรเจกต์',
    'about.founder.p18': 'ปัจจุบัน Neo คือ<b>นักพัฒนาหลักเพียงคนเดียวของ M.NationWorld ในช่วงแรกของโปรเจกต์</b>',
    'about.founder.p19': 'เนื่องจากโปรเจกต์อยู่ในช่วงแรก การพัฒนาจึงใช้แนวทาง <b>AI-assisted Development</b> เป็นหลัก โดยใช้เครื่องมือ AI เช่น DeepSeek ช่วยเขียนโค้ด วิเคราะห์โค้ด ดีบัก และแก้ปัญหา',
    'about.founder.p20': 'AI ถูกใช้เป็นเครื่องมือพัฒนาเป็นหลัก ส่วนการตัดสินใจด้านผลิตภัณฑ์ ทิศทางเทคนิค และการนำไปใช้ขั้นสุดท้ายยังเป็นหน้าที่ของ Neo',
