    'about.founder.p22': 'ดังนั้น โมเดลการพัฒนาปัจจุบันของ M.NationWorld จึงสรุปได้ว่า:',
    'about.founder.key.humanAi': '<b>Human-led · AI-assisted</b>',
    'about.founder.p23': 'นั่นคือ คนเป็นผู้ตัดสินใจด้านผลิตภัณฑ์และเทคนิค ส่วน AI ช่วยสนับสนุนการพัฒนา',
