    'about.founder.p25': 'ในอนาคตแพลตฟอร์มไม่เพียงมีเครื่องมือสร้างโลก แต่ยังหวังสร้างชุมชนที่ครีเอเตอร์พูดคุย ร่วมมือ และแบ่งปันผลงานกัน',
    'about.founder.p26': 'ดังนั้น Neo จึงวางแผนฟีเจอร์อย่างโพสต์ ข้อความส่วนตัว Channel Team ข้อมูลครีเอเตอร์ และการมีปฏิสัมพันธ์ในชุมชน พร้อมคิดถึงกฎของแพลตฟอร์ม การตรวจสอบเนื้อหา และระบบจัดการผู้ใช้',
    'about.founder.p27': 'ด้านการประยุกต์ใช้ AI Neo วางแผนใช้ AI สำหรับตรวจสอบเนื้อหา บริการลูกค้าแบบ AI บูรณาการข้อมูล สรุปเนื้อหา และช่วยจัดการแพลตฟอร์ม',
