    // ── Hero ──
    'about.hero.title': 'Về chúng tôi',
    'about.hero.sub': 'Gặp gỡ M.NationWorld — nền tảng dành cho những người sáng tạo thế giới hư cấu, cùng đội ngũ nhỏ phía sau.',

    // ── Chúng tôi là ai ──
    'about.who.title': 'Chúng tôi là ai',
    'about.who.p1': 'M.NationWorld là nền tảng trực tuyến dành riêng cho <b style="color:var(--color-on-surface)">việc xây dựng thế giới hư cấu</b>. Tại đây, bạn có thể thiết kế một thế giới hoàn toàn của riêng mình từ con số không — <b style="color:var(--color-on-surface)">vi quốc gia, khoa học viễn tưởng, kỳ ảo</b>, đều được: soạn hiến pháp, thiết kế quốc kỳ, thiết lập chính thể, viết lịch sử, và từng bước biến quốc gia trong trí tưởng tượng thành một thế giới bách khoa sống động.',
    'about.who.p2': 'Chúng tôi tin rằng ai cũng có một thế giới muốn sáng tạo. M.NationWorld tồn tại để hạ thấp rào cản sáng tạo hết mức có thể — để những người sáng tạo bình thường không biết lập trình hay thiết kế cũng có thể xây dựng quốc gia của riêng mình, từng khối một.',
    'about.who.p3': 'Nền tảng được phát triển và vận hành bởi <b style="color:var(--color-on-surface)">Slati Studio</b>, một studio phần mềm độc lập do nhà sáng lập Neo dẫn dắt — tự tay làm mọi thứ từ định vị sản phẩm, thiết kế giao diện đến viết code. Nhấn vào thẻ đội ngũ bên dưới để gặp chúng tôi.',

