    'about.features.nation.desc': 'Từ quốc kỳ, hiến pháp, chính thể đến mạch lịch sử, xây dựng quốc gia của bạn từng bước bằng quy trình hướng dẫn — chi tiết chuyên sâu cho người muốn đào sâu, còn người mới chỉ cần ba bước để bắt đầu.',
