    'about.studio.list.teamWorld': 'Thế giới gốc của nhóm',
    'about.studio.p13': 'Vì vậy, Slati Studio hy vọng M.NationWorld cuối cùng sẽ hình thành một môi trường sáng tạo thế giới cởi mở hơn. Triết lý cốt lõi có thể tóm tắt là:',
    'about.studio.quote1': 'Trao cho người dùng nhiều tự do sáng tạo nhất có thể, đồng thời hạ thấp rào cản tạo ra những thế giới phức tạp.',
    'about.studio.sec.product': '5. Thiết kế sản phẩm & tính năng',
    'about.studio.p14': 'Slati Studio chịu trách nhiệm về cấu trúc sản phẩm tổng thể và thiết kế tính năng của M.NationWorld. Các hệ thống cốt lõi được lập kế hoạch hiện nay bao gồm:',
    'about.studio.list.wb': 'Worldbuilding',
    'about.studio.list.wiki': 'Wiki',
