    'about.studio.list.userSub': 'Gói đăng ký người dùng',
    'about.studio.list.teamSub': 'Gói đăng ký nhóm',
    'about.studio.p15': 'Những tính năng này không tồn tại độc lập với nhau, mà được kết hợp quanh cốt lõi "xây dựng thế giới". Mục tiêu là hình thành một quy trình hoàn chỉnh: <b>tạo → chỉnh sửa → xuất bản → trưng bày → giao lưu → hợp tác → quản lý</b>.',
    'about.studio.sec.uiux': '6. Thiết kế UI/UX',
    'about.studio.p16': 'Slati Studio chịu trách nhiệm về toàn bộ thiết kế hình ảnh và hệ thống tương tác của M.NationWorld. Bao gồm:',
    'about.studio.list.cardUi2': 'Card UI',
    'about.studio.list.modular': 'Trang dạng mô-đun',
    'about.studio.list.wikiPage': 'Trang Wiki',
    'about.studio.list.dynamicBg': 'Nền Wiki động',
