    'about.studio.list.dataUi': 'Giao diện quản lý dữ liệu',
    'about.studio.list.mlUi': 'Giao diện đa ngôn ngữ',
    'about.studio.p17': 'Slati Studio đặc biệt coi trọng <b>trải nghiệm tùy chỉnh</b>. Wiki truyền thống thường yêu cầu người dùng tạo nội dung theo cấu trúc cố định, còn M.NationWorld muốn người dùng tự do hơn trong việc quyết định thế giới của mình nên được trình bày như thế nào.',
    'about.studio.p18': 'Vì vậy, mục tiêu của thiết kế UI/UX không chỉ là "đẹp", mà là:',
    'about.studio.quote2': 'Để người dùng thực sự kiểm soát nội dung của chính mình.',
    'about.studio.sec.fc': '7. FluidCanvas',
    'about.studio.p19': '<b>FluidCanvas</b> là công cụ sáng tạo và quản lý quan trọng trong hệ thống M.NationWorld. Slati Studio chịu trách nhiệm về thiết kế sản phẩm và lập kế hoạch tính năng của FluidCanvas. Công cụ này chủ yếu dùng để:',
    'about.studio.list.editArticle': 'Chỉnh sửa bài viết',
    'about.studio.list.mgmtWiki': 'Quản lý nội dung Wiki',
    'about.studio.list.mgmtPosts': 'Quản lý bài đăng',
