    'about.studio.sec.intro': '1. Introdução à Slati Studio',
    'about.studio.p1': '<b>Slati Studio</b> é o estúdio de desenvolvimento e a entidade principal do projeto M.NationWorld, responsável pela conceção do produto, pelo design, pelo desenvolvimento e pelo crescimento a longo prazo do M.NationWorld.',
    'about.studio.p2': 'A Slati Studio encontra-se atualmente numa fase inicial, e o M.NationWorld é o projeto central mais importante do estúdio neste momento.',
    'about.studio.p3': 'Ao contrário das empresas de software tradicionais com muitos departamentos e funcionários, a Slati Studio opera hoje num modelo de desenvolvimento individual compacto. Na fase inicial do M.NationWorld, Neo assumiu ao mesmo tempo vários papéis: líder de projeto, designer de produto, designer UI/UX e desenvolvedor principal.',
    'about.studio.p4': 'Por isso, na fase atual a Slati Studio aproxima-se mais de um <b>estúdio de software independente (Independent Software Studio)</b> liderado pelo seu fundador.',
    'about.studio.sec.relation': '2. Relação com o M.NationWorld',
    'about.studio.p5': 'A relação entre a Slati Studio e o M.NationWorld pode resumir-se assim:',
