    'about.studio.key.mnw': '<b>M.NationWorld</b>→ Produto central',
    'about.studio.p6': 'O M.NationWorld é hoje o projeto de produto mais importante da Slati Studio. A Slati Studio é responsável pela construção integral do M.NationWorld: posicionamento do produto, design de funcionalidades, UI/UX, desenvolvimento técnico, aplicações de IA, governança da plataforma e planeamento do desenvolvimento futuro.',
    'about.studio.p7': 'Por isso, o M.NationWorld não é um simples projeto web pessoal, mas um projeto de software de longo prazo desenvolvido e planeado continuamente pela Slati Studio.',
    'about.studio.sec.duties': '3. Responsabilidades centrais',
    'about.studio.p8': 'A responsabilidade da Slati Studio no projeto M.NationWorld não consiste apenas em "escrever código". O estúdio é responsável por transformar um conceito de produto, gradualmente, numa plataforma de software completa. As responsabilidades principais incluem:',
    'about.studio.sub.planning': 'Planeamento do produto',
    'about.studio.p9': 'Responsável por definir o M.NationWorld quanto a:',
    'about.studio.list.positioning': 'Posicionamento do produto',
    'about.studio.list.audience': 'Público-alvo',
    'about.studio.list.coreFeatures': 'Funcionalidades centrais',
    'about.studio.list.architecture': 'Arquitetura do produto',
    'about.studio.list.ux': 'Experiência do utilizador',
    'about.studio.list.bizModel': 'Modelo de negócio',
    'about.studio.list.globalDir': 'Direção de internacionalização',
    'about.studio.list.roadmap': 'Roteiro de desenvolvimento a longo prazo',
    'about.studio.p10': 'O M.NationWorld girava inicialmente em torno de um Wiki de nações fictícias e depois orientou-se gradualmente para uma <b>plataforma de criação de mundos (Worldbuilding Platform)</b> mais ampla.',
    'about.studio.p11': 'Este ajuste de posicionamento é também fruto do replaneamento da direção de longo prazo do projeto pela Slati Studio.',
    'about.studio.sec.wbPlatform': '4. Construção da plataforma de criação de mundos',
    'about.studio.p12': 'A Slati Studio é responsável por construir o sistema Worldbuilding central do M.NationWorld. O objetivo não é apenas oferecer um Wiki, mas permitir que os utilizadores criem, organizem, mostrem e mantenham livremente os seus próprios mundos. Os tipos de conteúdo previstos para o futuro incluem:',
    'about.studio.list.nation': 'Nações fictícias',
    'about.studio.list.history': 'História alternativa',
    'about.studio.list.city': 'Cidades fictícias',
    'about.studio.list.org': 'Organizações fictícias',
    'about.studio.list.politics': 'Sistemas políticos',
    'about.studio.list.gameWorld': 'Mundos de jogos',
    'about.studio.list.novelWorld': 'Mundos de romances',
    'about.studio.list.oc': 'OC',
    'about.studio.list.animeWorld': 'Mundos de anime',
    'about.studio.list.teamWorld': 'Mundos originais de equipa',
    'about.studio.p13': 'Por isso, a Slati Studio espera que o M.NationWorld acabe por formar um ambiente de criação de mundos mais aberto. A filosofia central pode resumir-se assim:',
    'about.studio.quote1': 'Dar aos utilizadores o máximo de liberdade criativa possível, ao mesmo tempo que se baixa a barreira de criar mundos complexos.',
    'about.studio.sec.product': '5. Design de produto e funcionalidades',
    'about.studio.p14': 'A Slati Studio é responsável pela estrutura geral do produto e pelo design de funcionalidades do M.NationWorld. Os sistemas centrais atualmente planeados incluem:',
    'about.studio.list.wb': 'Worldbuilding',
    'about.studio.list.wiki': 'Wiki',
    'about.studio.list.wysiwyg': 'Edição de conteúdo WYSIWYG',
    'about.studio.list.cardUi': 'Card UI',
    'about.studio.list.community': 'Comunidade',
