    'about.studio.list.teamSub': 'Subscrições de equipa',
    'about.studio.p15': 'Estas funcionalidades não existem de forma independente umas das outras; combinam-se em torno do núcleo da "criação de mundos". O objetivo é formar um fluxo completo: <b>criar → editar → publicar → mostrar → comunicar → colaborar → gerir</b>.',
    'about.studio.sec.uiux': '6. Design UI/UX',
    'about.studio.p16': 'A Slati Studio é responsável pelo design visual geral e pelo sistema de interação do M.NationWorld. Isto inclui:',
    'about.studio.list.cardUi2': 'Card UI',
    'about.studio.list.modular': 'Páginas modulares',
    'about.studio.list.wikiPage': 'Páginas de Wiki',
