    'about.studio.list.mlUi': 'Interface multilingue',
    'about.studio.p17': 'A Slati Studio dá especial importância à <b>experiência de personalização</b>. Os Wikis tradicionais costumam exigir a criação de conteúdo em estruturas fixas, enquanto o M.NationWorld quer que os utilizadores decidam com mais liberdade como o seu mundo deve ser apresentado.',
