    'about.studio.sec.fc': '7. FluidCanvas',
    'about.studio.p19': 'O <b>FluidCanvas</b> é uma ferramenta de criação e gestão importante no sistema M.NationWorld. A Slati Studio é responsável pelo design do produto e pelo planeamento das funcionalidades do FluidCanvas. É usado principalmente para:',
