    'about.studio.p20': 'O FluidCanvas está posicionado como uma consola de nível intermédio que liga a interface de utilizador comum aos dados subjacentes da plataforma. A sua filosofia central é:',
    'about.studio.quote3': 'Transformar funções complexas de gestão de dados e conteúdo num espaço de trabalho visual e intuitivo.',
    'about.studio.sec.dev': '8. Desenvolvimento de software',
    'about.studio.p21': 'A Slati Studio é responsável pelo desenvolvimento de software real do M.NationWorld. O projeto ainda está numa fase inicial, pelo que o desenvolvimento é assegurado sobretudo por Neo sozinho. O desenvolvimento segue o modelo <b>AI-assisted Development</b>, com ferramentas de IA como o DeepSeek para auxiliar em:',
    'about.studio.list.code': 'A escrita de código',
    'about.studio.list.analysis': 'A análise de código',
    'about.studio.list.impl': 'A implementação de funcionalidades',
    'about.studio.list.debug': 'Debug',
    'about.studio.list.troubleshoot': 'O diagnóstico de problemas',
    'about.studio.list.modify': 'A modificação de código',
    'about.studio.list.research': 'A investigação técnica',
    'about.studio.p22': 'Mas a IA não toma as decisões finais do projeto. Os requisitos de produto, a direção técnica, a lógica das funcionalidades, a revisão de código, a modificação, a integração, os testes e a adoção final de qualquer plano de implementação continuam a ser responsabilidade de Neo. Por isso, o modelo de desenvolvimento atual da Slati Studio pode resumir-se assim:',
    'about.studio.key.humanLed': '<b>Human-led Development + AI-assisted Development</b>Ou seja: as pessoas decidem, a IA auxilia o desenvolvimento.',
    'about.studio.sec.ai': '9. Aplicações de IA',
    'about.studio.p23': 'A Slati Studio planeia tornar a IA parte da infraestrutura da plataforma M.NationWorld, e não apenas uma função de chat. No futuro, a IA poderá participar em:',
