    'about.studio.list.categorize': 'A categorização de conteúdo',
    'about.studio.list.creatorAssist': 'A assistência a criadores',
    'about.studio.list.platformMgmt': 'A gestão da plataforma',
    'about.studio.p24': 'Quando a IA não consegue determinar se um conteúdo cumpre as regras da plataforma, este é entregue a pessoas para revisão adicional. Por isso, a Slati Studio espera construir um mecanismo de gestão híbrido de <b>automação com IA + moderação humana</b>.',
